def snakesAndLadders(board: list[list[int]]) -> int:
    n = len(board)
    def get_rc(sq):
        r = (sq - 1) // n
        c = (sq - 1) % n
        if r % 2 == 1: c = n - 1 - c
        return n - 1 - r, c
    from collections import deque
    q = deque([(1, 0)])
    visited = {1}
    while q:
        sq, moves = q.popleft()
        if sq == n * n: return moves
        for nxt in range(sq + 1, min(sq + 6, n * n) + 1):
            r, c = get_rc(nxt)
            dest = board[r][c] if board[r][c] != -1 else nxt
            if dest not in visited:
                visited.add(dest)
                q.append((dest, moves + 1))
    return -1

